CREATE TABLE IF NOT EXISTS org_departments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text UNIQUE NOT NULL, purpose text, status text NOT NULL DEFAULT 'Active', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS org_positions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), position_code text UNIQUE NOT NULL, title text NOT NULL, department_id uuid REFERENCES org_departments(id), reports_to_position_id uuid REFERENCES org_positions(id), employment_type text DEFAULT 'Full-time', level text, purpose text, responsibilities text, required_skills text, approved_headcount integer NOT NULL DEFAULT 1, filled_headcount integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'Approved', created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS org_positions_department_idx ON org_positions(department_id);
CREATE INDEX IF NOT EXISTS org_positions_manager_idx ON org_positions(reports_to_position_id);